import { useMemo } from 'react';

import { useLastDataRefresh } from 'contexts';
import {
  type CountriesBrandPowerExportResponse,
  type CountryExportData,
  type PeriodType,
  useGetCountriesExportQuery,
} from 'redux/api/bff';

import { EXPORT_COUNTRIES } from '../../constants';

const PERIODS: PeriodType[] = ['QTD', 'YTD'];

const BATCHES = [
  EXPORT_COUNTRIES.slice(0, 5).map((c) => c.code),
  EXPORT_COUNTRIES.slice(5, 10).map((c) => c.code),
  EXPORT_COUNTRIES.slice(10, 15).map((c) => c.code),
  EXPORT_COUNTRIES.slice(15, 20).map((c) => c.code),
  EXPORT_COUNTRIES.slice(20, 25).map((c) => c.code),
  EXPORT_COUNTRIES.slice(25, 30).map((c) => c.code),
];

export interface AllCountriesData {
  QTD: Record<string, CountryExportData>;
  YTD: Record<string, CountryExportData>;
}

function mergeBatches(
  responses: (CountriesBrandPowerExportResponse | undefined)[],
  period: PeriodType,
): Record<string, CountryExportData> {
  const result: Record<string, CountryExportData> = {};
  for (const response of responses) {
    const countries = response?.[period];
    if (countries) {
      Object.assign(result, countries);
    }
  }
  return result;
}

export const useAllCountriesData = (skip = false) => {
  const { lastDataRefreshKpisDateMonthYear } = useLastDataRefresh();
  const dt_end = lastDataRefreshKpisDateMonthYear?.power ?? '';

  const skipAll = !dt_end || skip;

  const batchArgs = (countries: string[]) => ({
    countries,
    dt_end,
    periods: PERIODS,
  });

  const firstBatch = useGetCountriesExportQuery(batchArgs(BATCHES[0]), {
    skip: skipAll,
  });
  const secondBatch = useGetCountriesExportQuery(batchArgs(BATCHES[1]), {
    skip: skipAll,
  });
  const thirdBatch = useGetCountriesExportQuery(batchArgs(BATCHES[2]), {
    skip: skipAll,
  });
  const fourthBatch = useGetCountriesExportQuery(batchArgs(BATCHES[3]), {
    skip: skipAll,
  });
  const fifthBatch = useGetCountriesExportQuery(batchArgs(BATCHES[4]), {
    skip: skipAll,
  });
  const sixthBatch = useGetCountriesExportQuery(batchArgs(BATCHES[5]), {
    skip: skipAll,
  });

  const allBatches = [
    firstBatch,
    secondBatch,
    thirdBatch,
    fourthBatch,
    fifthBatch,
    sixthBatch,
  ];

  const countries: AllCountriesData = useMemo(
    () => ({
      QTD: mergeBatches(
        allBatches.map((batch) => batch.data),
        'QTD',
      ),
      YTD: mergeBatches(
        allBatches.map((batch) => batch.data),
        'YTD',
      ),
    }),
    [
      firstBatch.data,
      secondBatch.data,
      thirdBatch.data,
      fourthBatch.data,
      fifthBatch.data,
      sixthBatch.data,
    ],
  );

  const loading =
    skipAll || allBatches.some((r) => r.isLoading || r.isFetching);

  const error = allBatches.some((r) => r.error)
    ? new Error('Failed to load country export data')
    : null;

  return { countries, loading, error };
};
